() => {
  // Find the container of the project cards
  const cards = document.querySelectorAll('[class]');
  const results = [];
  cards.forEach(el => {
    results.push({
      tag: el.tagName,
      class: el.className,
      style: el.getAttribute('style'),
      computedDisplay: getComputedStyle(el).display,
      computedOverflow: getComputedStyle(el).overflow,
      computedFlexWrap: getComputedStyle(el).flexWrap,
      computedWidth: getComputedStyle(el).width,
      computedMinWidth: getComputedStyle(el).minWidth,
      computedMaxWidth: getComputedStyle(el).maxWidth,
      scrollW: el.scrollWidth,
      clientW: el.clientWidth,
      text: el.textContent?.substring(0, 50)
    });
  });
  return results;
}

() => {
  const body = document.body;
  const app = body.firstElementChild;
  const children = Array.from(app.children);
  return children.map(c => ({
    tag: c.tagName,
    style: c.getAttribute('style'),
    display: getComputedStyle(c).display,
    overflow: getComputedStyle(c).overflow,
    flexWrap: getComputedStyle(c).flexWrap,
    gap: getComputedStyle(c).gap,
    scrollW: c.scrollWidth,
    clientW: c.clientWidth,
    childCount: c.children.length,
    text: c.textContent?.substring(0, 80)
  }));
}

