() => {
  // body has one child div, that div has one child div (wrapper), let me get all children recursively until I find the flex container
  let el = document.body;
  const path = [];
  while (el) {
    path.push({
      tag: el.tagName,
      childCount: el.children?.length,
      style: el.getAttribute?.('style'),
    });
    if (el.children?.length > 1) break;
    el = el.firstElementChild;
  }
  // Now get children of the element with multiple children
  const children = Array.from(el.children).map((c, i) => ({
    index: i,
    tag: c.tagName,
    style: c.getAttribute('style'),
    display: getComputedStyle(c).display,
    flexWrap: getComputedStyle(c).flexWrap,
    overflow: getComputedStyle(c).overflow,
    scrollW: c.scrollWidth,
    clientW: c.clientWidth,
    childCount: c.children.length,
    snippet: c.textContent?.substring(0, 40)
  }));
  return { path, children };
}

() => {
  // body > div#app > div(wrapper with max-width) > children
  const appDiv = document.body.children[0]; // div#app or similar
  const wrapper = appDiv.firstElementChild; // div with max-width: 1200px
  const wrapperChildren = Array.from(wrapper.children).map((c, i) => ({
    index: i,
    tag: c.tagName,
    style: c.getAttribute('style'),
    display: getComputedStyle(c).display,
    flexWrap: getComputedStyle(c).flexWrap,
    overflow: getComputedStyle(c).overflow,
    minWidth: getComputedStyle(c).minWidth,
    scrollW: c.scrollWidth,
    clientW: c.clientWidth,
    childCount: c.children.length,
    snippet: c.textContent?.substring(0, 40)
  }));
  return { wrapperId: wrapper.id, wrapperClass: wrapper.className, wrapperStyle: wrapper.getAttribute('style'), wrapperChildren };
}

